import Foundation

/// Fixed, human-written steps for people who already acted on a suspicious message.
/// These are never generated by a model, so they're always the same and always checked.
public enum RecoverySituation: String, CaseIterable, Sendable, Identifiable {
    case clickedLink = "clicked_link"
    case paid
    case sharedCodeOrPassword = "shared_code_or_password"
    case sharedPersonalInfo = "shared_personal_info"

    public var id: String { rawValue }

    public var label: String {
        switch self {
        case .clickedLink: "I clicked a link"
        case .paid: "I paid or sent money"
        case .sharedCodeOrPassword: "I shared a code or password"
        case .sharedPersonalInfo: "I shared personal details"
        }
    }

    public var steps: [String] {
        switch self {
        case .clickedLink:
            [
                "Don't enter anything else on that page. Close it.",
                "If you typed a password there, change it now on the real website or app, and anywhere you reuse it.",
                "Turn on two-step verification for that account, and watch it for activity you don't recognize.",
            ]
        case .paid:
            [
                "Call your bank or card company now, using the number on the back of your card or in their official app. Ask them to stop or reverse the payment.",
                "If you paid with a gift card, call the company that sold the card and tell them it was used in a scam.",
                "Report it at ReportFraud.ftc.gov (in the U.S.), and keep any receipts and messages.",
            ]
        case .sharedCodeOrPassword:
            [
                "Change the password for that account right away, from the real website or app.",
                "Sign out of all other devices in the account's security settings, and turn on two-step verification.",
                "If it was a bank code, call your bank using the number on your card and tell them.",
            ]
        case .sharedPersonalInfo:
            [
                "If you shared a card or account number, call your bank using the number on your card.",
                "If you shared your Social Security number, consider a free credit freeze with each of the three major credit bureaus.",
                "Go to IdentityTheft.gov (in the U.S.) for a step-by-step recovery plan.",
            ]
        }
    }
}
